    'footer.brandName': 'Mercosur Chamber of Commerce (CSO)',
    'footer.brandDescription': 'Civil Society Organization (CSO), independent, private, non-profit, based in Uruguay and with international scope, focused on strengthening trade, investment, business cooperation and economic integration between Latin America and the world.',
    'footer.brandDescription2': 'Independent institutional identity. Business and civil society activity within the MERCOSUR sphere and internationally, without governmental status or official representation of MERCOSUR.',
    'footer.brandDescription3': 'Active international agenda in civil society, trade, investment and development forums.',
